-- 'load' fed by a reader function, the edges of varargs and of
-- table.unpack/pack/move, and how 'coroutine.wrap' and 'coroutine.close'
-- carry a failure.
local function show(...)
  local n = select('#', ...)
  local t = {}
  for i = 1, n do
    local v = (select(i, ...))
    if type(v) == "string" then t[i] = string.format("%q", v)
    elseif v == nil then t[i] = "nil"
    elseif type(v) == "number" then t[i] = string.format("%.17g", v)
    else
      local ok, s = pcall(tostring, v)
      t[i] = ok and s or ("<" .. type(v) .. ">")
    end
  end
  return table.concat(t, "|")
end
local function rec(f, ...)
  local ok, e = pcall(f, ...)
  if ok then return "ok|" .. show(...) end
  return "err|" .. (tostring(e):gsub("^[^:]*:%d+: ", ""))
end

print("== load with a reader ==")
local function reader(parts)
  local i = 0
  return function()
    i = i + 1
    return parts[i]
  end
end
print(rec(load, reader{"return 1"}))
print(rec(load, reader{"return", " 1"}))
print(rec(load, reader{""}))
print(rec(load, reader{"return 1", ""}))
print(rec(load, reader{"return 1", "+"}))
print(rec(function() local f = load(reader{"return 1"}) return f and f() end))
print(rec(function() local f = load(reader{"return", " 42"}) return f and f() end))
print(rec(function() local f = load(reader{"local a = 1 return a"}) return f and f() end))
print(rec(load, reader{nil}))
print(rec(load, reader{5}))
print(rec(load, reader{true}))
print(rec(load, reader{{}}))
print(rec(load, reader{"return 1", 5}))
print(rec(function() return load(function() error("reader failed") end) end))
print(rec(function() return load(function() return nil, "extra" end) end))
print(rec(load, 5))
print(rec(load, function() end))
print(rec(load, reader{"\27Lua"}))
print(rec(function() local f = load(reader{"\27Lua\x54\x00\x19\x93\r\n\x1a\n"}) return type(f) end))
-- a reader that never answers nil never ends, so these stop
print(rec(function()
  local n = 0
  return load(function() n = n + 1 if n == 1 then return "return " elseif n == 2 then return "7" end end)()
end))
print(rec(function()
  local n = 0
  return load(function() n = n + 1 if n < 5 then return "return " elseif n == 5 then return "7" end end)()
end))

print("== varargs and select ==")
print(rec(function() return (function(...) return select("#", ...) end)(1, 2, 3) end))
print(rec(function() return (function(...) return select("#", ...) end)() end))
print(rec(function() return (function(...) return ... end)(1, 2, 3) end))
print(rec(function() return (function(...) local a = {...} return #a end)(1, 2, 3) end))
print(rec(function() return (function(...) return (...) end)(1, 2, 3) end))
print(rec(function() return (function(...) return select(-1, ...) end)(1, 2, 3) end))
print(rec(function() return (function(...) return select(-4, ...) end)(1, 2, 3) end))
print(rec(function() return (function(...) return select(0, ...) end)(1, 2) end))
print(rec(function() return (function(...) return select(4, ...) end)(1, 2, 3) end))
print(rec(function() return (function(...) return select("#", ...) end)(nil, nil) end))
print(rec(function() return (function(...) return #{...} end)(nil) end))
print(rec(table.pack))
print(rec(function() return table.pack(1, 2, 3).n end))
print(rec(function() return table.pack(nil, nil).n end))
print(rec(function() local p = table.pack() return p.n, #p end))

print("== table.unpack limits ==")
print(rec(table.unpack, {1, 2, 3}))
print(rec(table.unpack, {1, 2, 3}, 2))
print(rec(table.unpack, {1, 2, 3}, 1, 3))
print(rec(table.unpack, {1, 2, 3}, 1, 4))
print(rec(table.unpack, {1, 2, 3}, 2, 1))
print(rec(table.unpack, {}))
print(rec(table.unpack, {}, 1, 0))
print(rec(function() return select("#", table.unpack({1, 2, 3}, 1, 100000)) end))
print(rec(table.unpack, {1, 2, 3}, 0))
print(rec(table.unpack, {1, 2, 3}, -1))
print(rec(table.unpack, {1, 2, 3}, -3))
print(rec(table.unpack, {1, 2, 3}, -4))
print(rec(table.unpack, {1, 2, 3}, 1, -1))
print(rec(table.unpack, 5))
print(rec(table.unpack, {1}, 1.5))
print(rec(table.unpack, {1}, 1, 1.5))
print(rec(table.unpack, {}, 2 ^ 31))
print(rec(function() return #{table.unpack({1, 2, 3}, 1, 1000)} end))
print(rec(function() return select("#", table.unpack({1, 2, 3}, 1, 999)) end))
print(rec(function() return table.unpack({1, 2, 3}, 1, 2 ^ 30) end))

print("== table.move / insert / remove edges ==")
-- 'table.move' really does walk the range it is given, so a range of
-- 2^31 keeps both interpreters busy for half a minute; only the ranges
-- that are refused are asked here.
print(rec(table.move, {1, 2, 3}, 1, 3, 1))
print(rec(table.move, {1, 2, 3}, 1, 3, 2))
print(rec(table.move, {1, 2, 3}, 2, 3, 1))
print(rec(table.move, {1, 2, 3}, 1, 0, 1))
print(rec(table.move, {1, 2, 3}, 0, 2, 1))
print(rec(table.move, {1, 2, 3}, 1, 3, 0))
print(rec(table.move, {1, 2, 3}, 1, 3, 4))
print(rec(table.move, {}, 1, 0, 1, {}))
print(rec(table.move, {1}, 1, 1, 1, 5))
print(rec(table.move, {1, 2, 3}))
print(rec(table.move, {1, 2, 3}, "1", 3, 1))
print(rec(table.insert, {1, 2, 3}, 5))
print(rec(table.insert, {1, 2, 3}, 0, 5))
print(rec(table.insert, {1, 2, 3}, 4, 5))
print(rec(table.insert, {1, 2, 3}, 5, 6))
print(rec(table.insert, {1, 2, 3}, 1, 2, 3))
print(rec(table.insert, {}))
print(rec(table.remove, {1, 2, 3}))
print(rec(table.remove, {1, 2, 3}, 3))
print(rec(table.remove, {1, 2, 3}, 4))
print(rec(table.remove, {1, 2, 3}, 0))
print(rec(table.remove, {}))
print(rec(table.remove, {1, 2, 3}, 3, 4))

print("== coroutine.wrap and close ==")
local w = coroutine.wrap(function() coroutine.yield(1) return 2 end)
print(rec(function() return w() end), rec(function() return w() end))
print(rec(function() return coroutine.wrap(function() error("in co") end)() end))
print(rec(function() local f = coroutine.wrap(function() error("in co") end) f() return f() end))
print(rec(function() return coroutine.wrap(function() return 1 end)() end))
print(rec(function() return select("#", coroutine.wrap(function() coroutine.yield(1, 2, 3) end)()) end))
print(rec(coroutine.wrap, 5))
print(rec(coroutine.close, coroutine.create(function() end)))
print(rec(coroutine.close, coroutine.create(function() coroutine.yield() end)))
print(rec(function()
  local co = coroutine.create(function() coroutine.yield(1) end)
  coroutine.resume(co)
  return coroutine.close(co)
end))
print(rec(function()
  local co = coroutine.create(function()
    local ok, e = pcall(function() coroutine.yield() end)
    return ok, e
  end)
  coroutine.resume(co)
  coroutine.close(co)
  return coroutine.resume(co)
end))
print(rec(function()
  local co = coroutine.create(function()
    local x <close> = setmetatable({}, {__close = function() end})
    coroutine.yield()
    return "after"
  end)
  coroutine.resume(co)
  return coroutine.close(co)
end))
print(rec(coroutine.close, 5))
print(rec(coroutine.close))
print(rec(coroutine.isyieldable))
print(rec(function() return coroutine.isyieldable(coroutine.running()) end))
print(rec(function() local co = coroutine.create(function() return coroutine.isyieldable() end) return select(2, coroutine.resume(co)) end))
print(rec(coroutine.status, 5))
print(rec(coroutine.running))
print("done")
